// Responsive artwork recreates the supplied banner idea without baking in labels.
// Navigation and the non-interactive instrument pill remain real HTML text.
export function questBannerArt(){return `<svg viewBox="0 0 1600 140" preserveAspectRatio="none" aria-hidden="true" focusable="false"><defs><linearGradient id="quest-wave-light" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#d9efff"/><stop offset="1" stop-color="#56baf5"/></linearGradient><linearGradient id="quest-wave-blue" x1="0" y1="1" x2="1" y2="0"><stop stop-color="#148cee"/><stop offset="1" stop-color="#0754ab"/></linearGradient><linearGradient id="quest-wave-gold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffe17a"/><stop offset="1" stop-color="#ffc43b"/></linearGradient></defs><path d="M0 20 C55 42 70 103 155 140 H0Z" fill="url(#quest-wave-blue)"/><path d="M0 65 C53 75 92 122 148 140 H0Z" fill="url(#quest-wave-gold)"/><path d="M870 140 C1015 142 1070 81 1175 80 C1244 79 1250 114 1324 95 C1388 77 1394 32 1487 26 C1532 22 1561 35 1600 22 V140Z" fill="url(#quest-wave-light)"/><path d="M1125 140 C1255 132 1340 150 1457 72 L1600 0 V140Z" fill="url(#quest-wave-blue)"/><path d="M1478 0 H1568 C1545 14 1524 29 1493 27 C1480 26 1474 22 1480 19 C1507 26 1518 5 1531 0Z" fill="url(#quest-wave-gold)"/><g fill="#329de5" opacity=".25"><g transform="translate(1146 82) rotate(13)"><path d="M0 0 H7 V38 C7 49-13 54-18 43 C-22 33-6 26 0 30Z"/><path d="M7 0 C9 12 22 13 22 25 C22 32 17 37 13 39 C19 23 5 26 7 0Z"/></g><g transform="translate(1276 32) rotate(-14)"><path d="M0 0 H40 V8 H0Z M0 0 H6 V44 C5 55-14 58-18 48 C-21 40-9 34 0 38Z M34 0 H40 V37 C39 49 20 51 16 41 C13 33 25 27 34 31Z"/></g><g transform="translate(1347 98) rotate(24)"><path d="M0 0 H6 V31 C6 42-12 46-17 37 C-20 30-8 24 0 27Z M6 0 C8 9 17 10 17 18 C17 24 14 28 10 30 C14 18 4 21 6 0Z"/></g></g></svg>`;}
export function bannerInstrumentName({screen,page,instrumentChosen,instrument,libraryInstrument}){
 if(screen==='setup'&&page==='references'&&libraryInstrument)return libraryInstrument.name;
 return instrumentChosen&&instrument?instrument.name:'Choose your instrument';
}
